"""What is new in 0.2.0-alpha.9 (8 languages, informal "tu"): inline filters, smart search, single-question chat, MCP server."""
H_NEW = {"en": "New in 0.2.0-alpha.9", "ro": "Noutăți în 0.2.0-alpha.9", "fr": "Nouveautés de la 0.2.0-alpha.9", "it": "Novità della 0.2.0-alpha.9",
         "es": "Novedades de la 0.2.0-alpha.9", "pt": "Novidades da 0.2.0-alpha.9", "de": "Neu in 0.2.0-alpha.9", "hu": "Újdonságok a 0.2.0-alpha.9-ben"}
H_MID = {"en": "New in 0.2.0-alpha.3 to alpha.8", "ro": "Noutăți din 0.2.0-alpha.3 până la alpha.8", "fr": "Nouveautés de la 0.2.0-alpha.3 à la alpha.8", "it": "Novità dalla 0.2.0-alpha.3 alla alpha.8",
         "es": "Novedades de la 0.2.0-alpha.3 a la alpha.8", "pt": "Novidades da 0.2.0-alpha.3 à alpha.8", "de": "Neu von 0.2.0-alpha.3 bis alpha.8", "hu": "Újdonságok a 0.2.0-alpha.3-tól az alpha.8-ig"}
NEWS = [
 {"en": ("Filters right in the search box", "Type `ext:pdf`, `path:contracts`, `size:>1mb`, `after:2025-01`, `before:2025-06-30` or `re:INV-\\d+` (a regular expression) next to your words and the results narrow down. They work in the web page, on the command line and through the API."),
  "ro": ("Filtre direct în căsuța de căutare", "Scrie `ext:pdf`, `path:contracte`, `size:>1mb`, `after:2025-01`, `before:2025-06-30` sau `re:FACT-\\d+` (expresie regulată) lângă cuvintele tale și rezultatele se restrâng. Merg în pagina web, în linia de comandă și prin API."),
  "fr": ("Des filtres directement dans la zone de recherche", "Écris `ext:pdf`, `path:contrats`, `size:>1mb`, `after:2025-01`, `before:2025-06-30` ou `re:FAC-\\d+` (expression régulière) à côté de tes mots et les résultats se resserrent. Ils marchent dans la page web, en ligne de commande et via l’API."),
  "it": ("Filtri direttamente nella casella di ricerca", "Scrivi `ext:pdf`, `path:contratti`, `size:>1mb`, `after:2025-01`, `before:2025-06-30` o `re:FATT-\\d+` (espressione regolare) accanto alle tue parole e i risultati si restringono. Funzionano nella pagina web, da riga di comando e tramite API."),
  "es": ("Filtros directamente en la casilla de búsqueda", "Escribe `ext:pdf`, `path:contratos`, `size:>1mb`, `after:2025-01`, `before:2025-06-30` o `re:FAC-\\d+` (expresión regular) junto a tus palabras y los resultados se acotan. Funcionan en la página web, en la línea de comandos y a través de la API."),
  "pt": ("Filtros diretamente na caixa de pesquisa", "Escreve `ext:pdf`, `path:contratos`, `size:>1mb`, `after:2025-01`, `before:2025-06-30` ou `re:FAT-\\d+` (expressão regular) junto às tuas palavras e os resultados estreitam-se. Funcionam na página web, na linha de comandos e através da API."),
  "de": ("Filter direkt im Suchfeld", "Tippe `ext:pdf`, `path:vertraege`, `size:>1mb`, `after:2025-01`, `before:2025-06-30` oder `re:RE-\\d+` (regulärer Ausdruck) neben deine Wörter, und die Treffer werden eingegrenzt. Sie funktionieren auf der Webseite, in der Kommandozeile und über die API."),
  "hu": ("Szűrők közvetlenül a keresőmezőben", "Írd a szavaid mellé: `ext:pdf`, `path:szerzodesek`, `size:>1mb`, `after:2025-01`, `before:2025-06-30` vagy `re:SZ-\\d+` (reguláris kifejezés), és a találatok szűkülnek. Működnek a weboldalon, a parancssorban és az API-n keresztül.")},
 {"en": ("Smart search", "Tick “Smart search” and your local AI adds a few synonyms and related words (as a plain OR, so exact matches still rank first). The extra words are shown under the box. With no engine running, you simply get the normal search."),
  "ro": ("Căutare inteligentă", "Bifează „Căutare inteligentă” și AI-ul tău local adaugă câteva sinonime și cuvinte înrudite (ca un simplu OR, deci potrivirile exacte rămân primele). Cuvintele în plus apar sub căsuță. Fără motor pornit primești pur și simplu căutarea normală."),
  "fr": ("Recherche intelligente", "Coche « Recherche intelligente » et ton IA locale ajoute quelques synonymes et mots proches (en simple OR : les correspondances exactes restent en tête). Les mots ajoutés s’affichent sous la zone. Sans moteur en marche, tu obtiens simplement la recherche normale."),
  "it": ("Ricerca intelligente", "Spunta «Ricerca intelligente» e la tua IA locale aggiunge qualche sinonimo e parola affine (come semplice OR: le corrispondenze esatte restano in testa). Le parole aggiunte compaiono sotto la casella. Senza motore attivo ottieni la normale ricerca."),
  "es": ("Búsqueda inteligente", "Marca «Búsqueda inteligente» y tu IA local añade algunos sinónimos y palabras afines (como un simple OR: las coincidencias exactas siguen primero). Las palabras añadidas se muestran bajo la casilla. Sin motor en marcha obtienes la búsqueda normal."),
  "pt": ("Pesquisa inteligente", "Marca «Pesquisa inteligente» e a tua IA local acrescenta alguns sinónimos e palavras afins (como um simples OR: as correspondências exatas continuam à frente). As palavras acrescentadas aparecem debaixo da caixa. Sem motor ligado recebes a pesquisa normal."),
  "de": ("Intelligente Suche", "Hake „Intelligente Suche“ an, und deine lokale KI ergänzt ein paar Synonyme und verwandte Wörter (als einfaches OR, exakte Treffer stehen also weiter vorn). Die zusätzlichen Wörter erscheinen unter dem Feld. Ohne laufende Engine bekommst du die normale Suche."),
  "hu": ("Okos keresés", "Jelöld be az „Okos keresés” négyzetet, és a helyi MI hozzáad néhány szinonimát és rokon szót (egyszerű OR-ként, így a pontos találatok maradnak elöl). A hozzáadott szavak a mező alatt látszanak. Futó motor nélkül a szokásos keresést kapod.")},
 {"en": ("Single-question chat", "Tick “Each question on its own” and the chat forgets earlier questions: every answer comes only from your documents, with its sources."),
  "ro": ("Chat cu întrebări separate", "Bifează „Fiecare întrebare separat” și chatul uită întrebările anterioare: fiecare răspuns vine doar din documentele tale, cu sursele lui."),
  "fr": ("Chat question par question", "Coche « Chaque question à part » et le chat oublie les questions précédentes : chaque réponse vient uniquement de tes documents, avec ses sources."),
  "it": ("Chat a domanda singola", "Spunta «Ogni domanda a sé» e la chat dimentica le domande precedenti: ogni risposta viene solo dai tuoi documenti, con le sue fonti."),
  "es": ("Chat de pregunta única", "Marca «Cada pregunta por separado» y el chat olvida las preguntas anteriores: cada respuesta sale solo de tus documentos, con sus fuentes."),
  "pt": ("Chat de pergunta única", "Marca «Cada pergunta à parte» e o chat esquece as perguntas anteriores: cada resposta vem só dos teus documentos, com as suas fontes."),
  "de": ("Chat mit Einzelfragen", "Hake „Jede Frage einzeln“ an, und der Chat vergisst frühere Fragen: Jede Antwort stammt nur aus deinen Dokumenten, mit ihren Quellen."),
  "hu": ("Egykérdéses csevegés", "Jelöld be a „Minden kérdés külön” négyzetet, és a csevegés elfelejti a korábbi kérdéseket: minden válasz csak a dokumentumaidból származik, forrásokkal.")},
 {"en": ("An MCP server for other AI apps", "`cartacolibri mcp` lets other AI applications search your library, read a document and ask questions about it through the Model Context Protocol. It is read-only, runs on your computer and only reaches documents that search has returned."),
  "ro": ("Server MCP pentru alte aplicații AI", "`cartacolibri mcp` lasă alte aplicații AI să-ți caute în bibliotecă, să citească un document și să pună întrebări despre el prin Model Context Protocol. E doar în citire, rulează pe calculatorul tău și ajunge doar la documentele returnate de căutare."),
  "fr": ("Un serveur MCP pour d’autres applications d’IA", "`cartacolibri mcp` permet à d’autres applications d’IA de chercher dans ta bibliothèque, de lire un document et de l’interroger via le Model Context Protocol. Il est en lecture seule, tourne sur ton ordinateur et n’atteint que les documents renvoyés par la recherche."),
  "it": ("Un server MCP per altre app di IA", "`cartacolibri mcp` permette ad altre applicazioni di IA di cercare nella tua biblioteca, leggere un documento e fargli domande tramite il Model Context Protocol. È di sola lettura, gira sul tuo computer e raggiunge solo i documenti restituiti dalla ricerca."),
  "es": ("Un servidor MCP para otras apps de IA", "`cartacolibri mcp` permite que otras aplicaciones de IA busquen en tu biblioteca, lean un documento y le hagan preguntas mediante el Model Context Protocol. Es de solo lectura, se ejecuta en tu ordenador y solo llega a los documentos que devolvió la búsqueda."),
  "pt": ("Um servidor MCP para outras apps de IA", "`cartacolibri mcp` permite que outras aplicações de IA pesquisem na tua biblioteca, leiam um documento e façam perguntas sobre ele através do Model Context Protocol. É só de leitura, corre no teu computador e só chega aos documentos devolvidos pela pesquisa."),
  "de": ("Ein MCP-Server für andere KI-Apps", "`cartacolibri mcp` lässt andere KI-Anwendungen über das Model Context Protocol in deiner Bibliothek suchen, ein Dokument lesen und Fragen dazu stellen. Er ist nur lesend, läuft auf deinem Rechner und erreicht nur Dokumente, die die Suche geliefert hat."),
  "hu": ("MCP-szerver más MI-alkalmazásoknak", "A `cartacolibri mcp` lehetővé teszi, hogy más MI-alkalmazások a Model Context Protocolon át keressenek a könyvtáradban, elolvassanak egy dokumentumot és kérdezzenek róla. Csak olvasható, a gépeden fut, és csak a keresés által visszaadott dokumentumokat éri el.")},
 {"en": ('A digest of what is new', '`cartacolibri digest NAME` re-runs a saved search and reports only the documents that appeared since last time. Add `--every 60` to repeat hourly, `--out report.md` to append to a file and `--summarize` to get a short summary from your local AI.'), "ro": ('Rezumat cu ce e nou', '`cartacolibri digest NUME` reia o căutare salvată și raportează doar documentele apărute de la ultima rulare. Adaugă `--every 60` ca să se repete din oră în oră, `--out raport.md` ca să adauge într-un fișier și `--summarize` pentru un scurt rezumat de la AI-ul tău local.'), "fr": ('Un récapitulatif des nouveautés', '`cartacolibri digest NOM` relance une recherche enregistrée et ne signale que les documents apparus depuis la dernière fois. Ajoute `--every 60` pour répéter toutes les heures, `--out rapport.md` pour ajouter à un fichier et `--summarize` pour un court résumé par ton IA locale.'), "it": ('Un riepilogo delle novità', '`cartacolibri digest NOME` rilancia una ricerca salvata e segnala solo i documenti comparsi dall’ultima volta. Aggiungi `--every 60` per ripetere ogni ora, `--out rapporto.md` per accodare a un file e `--summarize` per un breve riassunto della tua IA locale.'), "es": ('Un resumen de las novedades', '`cartacolibri digest NOMBRE` repite una búsqueda guardada e informa solo de los documentos que aparecieron desde la última vez. Añade `--every 60` para repetir cada hora, `--out informe.md` para añadir a un archivo y `--summarize` para un resumen corto de tu IA local.'), "pt": ('Um resumo das novidades', '`cartacolibri digest NOME` repete uma pesquisa guardada e indica só os documentos que apareceram desde a última vez. Acrescenta `--every 60` para repetir de hora a hora, `--out relatorio.md` para juntar a um ficheiro e `--summarize` para um resumo curto da tua IA local.'), "de": ('Eine Zusammenfassung des Neuen', '`cartacolibri digest NAME` führt eine gespeicherte Suche erneut aus und meldet nur die Dokumente, die seit dem letzten Mal hinzugekommen sind. Mit `--every 60` wiederholt es stündlich, mit `--out bericht.md` hängt es an eine Datei an, mit `--summarize` liefert deine lokale KI eine kurze Zusammenfassung.'), "hu": ('Összefoglaló az újdonságokról', 'A `cartacolibri digest NÉV` újra lefuttat egy mentett keresést, és csak az utolsó futás óta megjelent dokumentumokat jelzi. A `--every 60` óránként ismétli, az `--out jelentes.md` fájlhoz fűz, a `--summarize` pedig rövid összefoglalót kér a helyi MI-től.')},
 {"en": ('Know how far to trust an answer', 'Every chat answer now shows a “Grounding” score: how much of each sentence is really found in the sources it cites, with sentences to double-check and numbers that appear in no source.'), "ro": ('Afli cât de mult poți avea încredere într-un răspuns', 'Fiecare răspuns din chat arată acum un scor „Susținere în surse”: cât din fiecare propoziție se găsește cu adevărat în sursele citate, cu propozițiile de verificat și numerele care nu apar în nicio sursă.'), "fr": ('Savoir jusqu’où se fier à une réponse', 'Chaque réponse du chat affiche désormais un score « Ancrage dans les sources » : la part de chaque phrase réellement retrouvée dans les sources citées, avec les phrases à revérifier et les nombres absents de toute source.'), "it": ('Sapere quanto fidarsi di una risposta', 'Ogni risposta della chat mostra ora un punteggio «Aderenza alle fonti»: quanta parte di ogni frase si trova davvero nelle fonti citate, con le frasi da ricontrollare e i numeri che non compaiono in nessuna fonte.'), "es": ('Saber cuánto fiarte de una respuesta', 'Cada respuesta del chat muestra ahora una puntuación «Respaldo en las fuentes»: cuánto de cada frase se encuentra de verdad en las fuentes citadas, con las frases por revisar y los números que no aparecen en ninguna fuente.'), "pt": ('Saber quanto confiar numa resposta', 'Cada resposta do chat mostra agora uma pontuação «Respaldo nas fontes»: quanto de cada frase se encontra mesmo nas fontes citadas, com as frases a rever e os números que não aparecem em nenhuma fonte.'), "de": ('Wissen, wie weit du einer Antwort trauen kannst', 'Jede Chat-Antwort zeigt jetzt einen Wert „Belegt durch Quellen“: wie viel jedes Satzes tatsächlich in den zitierten Quellen steht, mit den Sätzen zum Nachprüfen und Zahlen, die in keiner Quelle vorkommen.'), "hu": ('Tudd, mennyire bízhatsz egy válaszban', 'Minden csevegésválasz mostantól „Forrásokkal alátámasztva” pontszámot mutat: az egyes mondatok mekkora része található meg valóban az idézett forrásokban, az ellenőrzendő mondatokkal és a sehol sem szereplő számokkal.')},
 {"en": ('Compare two documents, and see every name and number', 'Tick two documents and press “Compare 2” to see, sentence by sentence, what differs between two versions. “Names & numbers” lists every email, link, money amount, date and phone number across your library, and where it appears. On the command line: `compare` and `entities`.'), "ro": ('Compară două documente și vezi toate numele și numerele', 'Bifează două documente și apasă „Compară 2” ca să vezi, propoziție cu propoziție, ce diferă între două versiuni. „Nume și numere” listează toate emailurile, linkurile, sumele, datele și telefoanele din bibliotecă și unde apar. În linia de comandă: `compare` și `entities`.'), "fr": ('Compare deux documents et vois tous les noms et nombres', 'Coche deux documents et appuie sur « Comparer 2 » pour voir, phrase par phrase, ce qui diffère entre deux versions. « Noms et nombres » liste tous les e-mails, liens, montants, dates et téléphones de ta bibliothèque, et où ils apparaissent. En ligne de commande : `compare` et `entities`.'), "it": ('Confronta due documenti e vedi tutti i nomi e i numeri', 'Spunta due documenti e premi «Confronta 2» per vedere, frase per frase, cosa differisce tra due versioni. «Nomi e numeri» elenca tutte le e-mail, i link, gli importi, le date e i telefoni della tua biblioteca e dove compaiono. Da riga di comando: `compare` ed `entities`.'), "es": ('Compara dos documentos y mira todos los nombres y números', 'Marca dos documentos y pulsa «Comparar 2» para ver, frase a frase, qué difiere entre dos versiones. «Nombres y números» lista todos los correos, enlaces, importes, fechas y teléfonos de tu biblioteca y dónde aparecen. En la línea de comandos: `compare` y `entities`.'), "pt": ('Compara dois documentos e vê todos os nomes e números', 'Marca dois documentos e carrega em «Comparar 2» para ver, frase a frase, o que difere entre duas versões. «Nomes e números» lista todos os e-mails, links, valores, datas e telefones da tua biblioteca e onde aparecem. Na linha de comandos: `compare` e `entities`.'), "de": ('Zwei Dokumente vergleichen und alle Namen und Zahlen sehen', 'Hake zwei Dokumente an und drücke „2 vergleichen“, um Satz für Satz zu sehen, was sich zwischen zwei Fassungen unterscheidet. „Namen & Zahlen“ listet alle E-Mails, Links, Beträge, Daten und Telefonnummern deiner Bibliothek und wo sie vorkommen. In der Kommandozeile: `compare` und `entities`.'), "hu": ('Hasonlíts össze két dokumentumot, és lásd az összes nevet és számot', 'Jelölj be két dokumentumot, és nyomd meg a „2 összehasonlítása” gombot: mondatonként látod, mi tér el két változat között. A „Nevek és számok” felsorolja a könyvtár összes e-mailjét, linkjét, összegét, dátumát és telefonszámát, és hogy hol szerepelnek. Parancssorban: `compare` és `entities`.')},
 {"en": ('Spot contradictions, see the map of topics, track what changed', "“Conflicts” lists sentences in different documents that agree except for a number or a date (500 vs 550). “Topic map” groups your documents by what they are about. “What's new” lists what changed since a date. On the command line: `conflicts`, `topics`, `changes --since`."), "ro": ('Găsești contradicții, vezi harta subiectelor, urmărești ce s-a schimbat', '„Contradicții” listează propoziții din documente diferite care sunt la fel, mai puțin un număr sau o dată (500 față de 550). „Harta subiectelor” grupează documentele după ce tratează. „Ce e nou” arată ce s-a schimbat de la o dată. În linia de comandă: `conflicts`, `topics`, `changes --since`.'), "fr": ('Repère les contradictions, vois la carte des sujets, suis ce qui a changé', '« Contradictions » liste les phrases de documents différents identiques à un nombre ou une date près (500 contre 550). « Carte des sujets » regroupe tes documents par thème. « Nouveautés » liste ce qui a changé depuis une date. En ligne de commande : `conflicts`, `topics`, `changes --since`.'), "it": ('Individua le contraddizioni, vedi la mappa dei temi, segui cosa è cambiato', '«Contraddizioni» elenca frasi di documenti diversi uguali tranne un numero o una data (500 contro 550). «Mappa dei temi» raggruppa i documenti per argomento. «Novità» elenca cosa è cambiato da una data. Da riga di comando: `conflicts`, `topics`, `changes --since`.'), "es": ('Detecta contradicciones, mira el mapa de temas, sigue lo que cambió', '«Contradicciones» lista frases de documentos distintos iguales salvo un número o una fecha (500 frente a 550). «Mapa de temas» agrupa tus documentos por tema. «Novedades» lista lo que cambió desde una fecha. En la línea de comandos: `conflicts`, `topics`, `changes --since`.'), "pt": ('Deteta contradições, vê o mapa de temas, acompanha o que mudou', '«Contradições» lista frases de documentos diferentes iguais exceto num número ou data (500 contra 550). «Mapa de temas» agrupa os teus documentos por assunto. «Novidades» lista o que mudou desde uma data. Na linha de comandos: `conflicts`, `topics`, `changes --since`.'), "de": ('Widersprüche aufspüren, Themenkarte sehen, Änderungen verfolgen', '„Widersprüche“ listet Sätze aus verschiedenen Dokumenten, die bis auf eine Zahl oder ein Datum gleich sind (500 gegen 550). Die „Themenkarte“ gruppiert deine Dokumente nach Thema. „Was ist neu“ zeigt, was sich seit einem Datum geändert hat. In der Kommandozeile: `conflicts`, `topics`, `changes --since`.'), "hu": ('Találd meg az ellentmondásokat, nézd a tématérképet, kövesd a változásokat', 'Az „Ellentmondások” felsorolja a különböző dokumentumok azon mondatait, amelyek egy számban vagy dátumban térnek el (500 és 550). A „Tématérkép” téma szerint csoportosítja a dokumentumokat. A „Mi az új” megmutatja, mi változott egy dátum óta. Parancssorban: `conflicts`, `topics`, `changes --since`.')},
 {"en": ('Fact-check your own text against your library', 'Paste a draft into “Fact-check my text” and every sentence is marked supported, partly supported, numbers differ or not found, with the best evidence from your documents. “Dossier” gathers everything your library says about a name or term, with its dates and amounts. Other AI apps get both through the MCP server.'), "ro": ('Verifici textul tău față de bibliotecă', 'Lipește o ciornă în „Verifică textul meu” și fiecare propoziție e marcată: susținută, parțial, numerele diferă sau negăsită, cu cea mai bună dovadă din documentele tale. „Dosar” adună tot ce spune biblioteca despre un nume sau termen, cu datele și sumele lui. Alte aplicații AI le primesc pe ambele prin serverul MCP.'), "fr": ('Vérifie ton propre texte face à ta bibliothèque', 'Colle un brouillon dans « Vérifier mon texte » : chaque phrase est marquée confirmée, en partie, nombres différents ou introuvable, avec la meilleure preuve de tes documents. « Dossier » rassemble tout ce que ta bibliothèque dit d’un nom ou d’un terme, avec ses dates et montants. Les autres applications d’IA y accèdent via le serveur MCP.'), "it": ('Verifica il tuo testo rispetto alla biblioteca', 'Incolla una bozza in «Verifica il mio testo» e ogni frase è segnata come confermata, in parte, numeri diversi o non trovata, con la migliore prova dai tuoi documenti. «Dossier» raccoglie tutto ciò che la biblioteca dice di un nome o termine, con date e importi. Le altre app di IA li ottengono tramite il server MCP.'), "es": ('Verifica tu propio texto frente a tu biblioteca', 'Pega un borrador en «Verificar mi texto» y cada frase se marca como respaldada, en parte, números distintos o no encontrada, con la mejor prueba de tus documentos. «Dosier» reúne todo lo que tu biblioteca dice de un nombre o término, con sus fechas e importes. Otras apps de IA acceden a ambos por el servidor MCP.'), "pt": ('Verifica o teu próprio texto face à biblioteca', 'Cola um rascunho em «Verificar o meu texto» e cada frase fica marcada como confirmada, em parte, números diferentes ou não encontrada, com a melhor prova dos teus documentos. «Dossiê» reúne tudo o que a tua biblioteca diz de um nome ou termo, com as suas datas e valores. Outras apps de IA acedem a ambos pelo servidor MCP.'), "de": ('Den eigenen Text gegen deine Bibliothek prüfen', 'Füge einen Entwurf in „Meinen Text prüfen“ ein, und jeder Satz wird als belegt, teilweise, Zahlen weichen ab oder nicht gefunden markiert, mit dem besten Beleg aus deinen Dokumenten. Das „Dossier“ sammelt alles, was deine Bibliothek zu einem Namen oder Begriff sagt, mit Daten und Beträgen. Andere KI-Apps erreichen beides über den MCP-Server.'), "hu": ('Ellenőrizd a saját szövegedet a könyvtárad alapján', 'Illessz be egy vázlatot a „Szövegem ellenőrzése” ablakba, és minden mondatot megjelölök: alátámasztva, részben, a számok eltérnek vagy nincs meg, a dokumentumaid legjobb bizonyítékával. A „Dosszié” összegyűjt mindent, amit a könyvtár egy névről vagy fogalomról mond, dátumokkal és összegekkel. Más MI-alkalmazások az MCP-szerveren át érik el mindkettőt.')},
 {"en": ('Ask about a time range, and get digests by e-mail file', "In the chat, pick “Documents from … to …” and the answer comes only from documents modified in that period (CLI: `chat --since --until`). The topic map is now a picture of bubbles you can click. `digest --mail-to you@example.org` also saves each report as an e-mail file in the outbox folder; add `--sendmail` to hand it to your computer's own mail program. Nothing else leaves your computer."), "ro": ('Întrebi pe un interval de timp și primești rezumatele ca fișier email', 'În chat alegi „Documente din … până în …” și răspunsul vine doar din documentele modificate în perioada aceea (în linia de comandă: `chat --since --until`). Harta subiectelor e acum o imagine cu bule pe care poți apăsa. `digest --mail-to tu@example.org` salvează fiecare raport și ca fișier email în folderul outbox; adaugă `--sendmail` ca să-l dai programului de poștă al calculatorului tău. Nimic altceva nu iese din calculator.'), "fr": ('Interroge sur une période et reçois les récapitulatifs en fichier e-mail', 'Dans le chat, choisis « Documents depuis … jusqu’à … » et la réponse vient seulement des documents modifiés sur cette période (en ligne de commande : `chat --since --until`). La carte des sujets est désormais une image de bulles cliquables. `digest --mail-to toi@example.org` enregistre aussi chaque rapport comme fichier e-mail dans le dossier outbox ; ajoute `--sendmail` pour le confier au programme de messagerie de ton ordinateur. Rien d’autre ne quitte ton ordinateur.'), "it": ('Chiedi su un intervallo di tempo e ricevi i riepiloghi come file e-mail', 'Nella chat scegli «Documenti dal … al …» e la risposta viene solo dai documenti modificati in quel periodo (da riga di comando: `chat --since --until`). La mappa dei temi è ora un’immagine di bolle cliccabili. `digest --mail-to te@example.org` salva ogni rapporto anche come file e-mail nella cartella outbox; aggiungi `--sendmail` per passarlo al programma di posta del tuo computer. Nient’altro lascia il tuo computer.'), "es": ('Pregunta sobre un periodo y recibe los resúmenes como archivo de correo', 'En el chat elige «Documentos desde … hasta …» y la respuesta sale solo de documentos modificados en ese periodo (línea de comandos: `chat --since --until`). El mapa de temas es ahora una imagen de burbujas en las que puedes pulsar. `digest --mail-to tu@example.org` guarda además cada informe como archivo de correo en la carpeta outbox; añade `--sendmail` para entregarlo al programa de correo de tu ordenador. Nada más sale de tu ordenador.'), "pt": ('Pergunta sobre um período e recebe os resumos como ficheiro de e-mail', 'No chat escolhe «Documentos desde … até …» e a resposta vem só de documentos modificados nesse período (linha de comandos: `chat --since --until`). O mapa de temas é agora uma imagem de bolhas em que podes clicar. `digest --mail-to tu@example.org` guarda também cada relatório como ficheiro de e-mail na pasta outbox; acrescenta `--sendmail` para o entregar ao programa de correio do teu computador. Nada mais sai do teu computador.'), "de": ('Zeitraum erfragen und Zusammenfassungen als E-Mail-Datei erhalten', 'Wähle im Chat „Dokumente ab … bis …“, und die Antwort stammt nur aus Dokumenten, die in dieser Zeit geändert wurden (Kommandozeile: `chat --since --until`). Die Themenkarte ist jetzt ein Bild aus anklickbaren Blasen. `digest --mail-to du@example.org` speichert jeden Bericht auch als E-Mail-Datei im Ordner outbox; mit `--sendmail` übergibst du ihn dem Mailprogramm deines Rechners. Sonst verlässt nichts deinen Rechner.'), "hu": ('Kérdezz egy időszakról, és kapd az összefoglalókat e-mail fájlként', 'A csevegésben válaszd a „Dokumentumok innen … eddig …” mezőket, és a válasz csak az adott időszakban módosult dokumentumokból származik (parancssorban: `chat --since --until`). A tématérkép mostantól kattintható buborékokból álló kép. A `digest --mail-to te@example.org` minden jelentést e-mail fájlként is elment az outbox mappába; a `--sendmail` átadja a gép saját levelezőprogramjának. Más nem hagyja el a gépedet.')},
 {"en": ("Connect the chat services you know, and compare them", "`cartacolibri providers` lists Ollama, LM Studio, Mistral, OpenAI, Gemini, Cohere, NVIDIA, Claude and Meta; `--provider NAME:MODEL` uses one on chat and tasks, and `versus` asks several the same question over the same passages. Cloud services need `--allow-cloud` and a key, because your passages are sent to them."),
  "ro": ("Conectează serviciile de chat pe care le știi și compară-le", "`cartacolibri providers` listează Ollama, LM Studio, Mistral, OpenAI, Gemini, Cohere, NVIDIA, Claude și Meta; `--provider NUME:MODEL` folosește unul la chat și sarcini, iar `versus` pune aceeași întrebare mai multora pe aceleași pasaje. Serviciile din cloud cer `--allow-cloud` și o cheie, fiindcă pasajele tale le sunt trimise."),
  "fr": ("Connecte les services de chat que tu connais et compare-les", "`cartacolibri providers` liste Ollama, LM Studio, Mistral, OpenAI, Gemini, Cohere, NVIDIA, Claude et Meta ; `--provider NOM:MODÈLE` en utilise un pour le chat et les tâches, et `versus` pose la même question à plusieurs sur les mêmes passages. Les services cloud demandent `--allow-cloud` et une clé, car tes passages leur sont envoyés."),
  "it": ("Collega i servizi di chat che conosci e confrontali", "`cartacolibri providers` elenca Ollama, LM Studio, Mistral, OpenAI, Gemini, Cohere, NVIDIA, Claude e Meta; `--provider NOME:MODELLO` ne usa uno per chat e attività, e `versus` pone la stessa domanda a più servizi sugli stessi passaggi. I servizi cloud richiedono `--allow-cloud` e una chiave, perché i tuoi passaggi vengono inviati."),
  "es": ("Conecta los servicios de chat que conoces y compáralos", "`cartacolibri providers` lista Ollama, LM Studio, Mistral, OpenAI, Gemini, Cohere, NVIDIA, Claude y Meta; `--provider NOMBRE:MODELO` usa uno en el chat y las tareas, y `versus` hace la misma pregunta a varios sobre los mismos pasajes. Los servicios en la nube piden `--allow-cloud` y una clave, porque se les envían tus pasajes."),
  "pt": ("Liga os serviços de chat que conheces e compara-os", "`cartacolibri providers` lista Ollama, LM Studio, Mistral, OpenAI, Gemini, Cohere, NVIDIA, Claude e Meta; `--provider NOME:MODELO` usa um no chat e nas tarefas, e `versus` faz a mesma pergunta a vários sobre os mesmos excertos. Os serviços na nuvem pedem `--allow-cloud` e uma chave, porque os teus excertos lhes são enviados."),
  "de": ("Verbinde die Chat-Dienste, die du kennst, und vergleiche sie", "`cartacolibri providers` listet Ollama, LM Studio, Mistral, OpenAI, Gemini, Cohere, NVIDIA, Claude und Meta; `--provider NAME:MODELL` nutzt einen im Chat und bei Aufgaben, und `versus` stellt mehreren dieselbe Frage zu denselben Textstellen. Cloud-Dienste brauchen `--allow-cloud` und einen Schlüssel, weil deine Textstellen dorthin gesendet werden."),
  "hu": ("Kapcsold össze az ismert csevegőszolgáltatásokat, és hasonlítsd össze őket", "A `cartacolibri providers` kilistázza az Ollama, LM Studio, Mistral, OpenAI, Gemini, Cohere, NVIDIA, Claude és Meta szolgáltatást; a `--provider NÉV:MODELL` egyet használ a csevegésben és a feladatokban, a `versus` pedig ugyanazt a kérdést teszi fel többnek ugyanazokra a szövegrészekre. A felhőszolgáltatásokhoz `--allow-cloud` és kulcs kell, mert a szövegrészeid elküldésre kerülnek.")},
 {"en": ("Chat history, and a button to the web-grab browser", "Under the chat there is now a list of your past conversations: search them, open one to read it and carry on where you stopped, delete one or all. They are kept only in your browser. In “Bring things in” a new button opens the web-grab browser on the same library. You can also save the whole history as one file and import it back; it is the same open format Colibri Companion uses ([docs/CHAT-HISTORY.md](../CHAT-HISTORY.md))."),
  "ro": ("Istoric chat și buton către browserul web-grab", "Sub chat găsești acum lista conversațiilor tale: le cauți, deschizi una ca s-o citești și s-o continui de unde ai rămas, ștergi una sau pe toate. Se păstrează doar în browserul tău. În „Adu lucruri din altă parte” un buton nou deschide browserul web-grab pe aceeași bibliotecă. Poți salva tot istoricul într-un singur fișier și îl poți importa înapoi; e același format deschis pe care îl folosește Colibri Companion ([docs/CHAT-HISTORY.ro.md](../CHAT-HISTORY.ro.md))."),
  "fr": ("Historique du chat et bouton vers le navigateur web-grab", "Sous le chat se trouve maintenant la liste de tes conversations : cherche-les, ouvre-en une pour la relire et continuer là où tu t’étais arrêté, supprime-en une ou toutes. Elles ne sont gardées que dans ton navigateur. Dans « Importer des éléments », un nouveau bouton ouvre le navigateur web-grab sur la même bibliothèque. Tu peux aussi enregistrer tout l’historique dans un fichier et le réimporter ; c’est le même format ouvert que Colibri Companion ([docs/CHAT-HISTORY.fr.md](../CHAT-HISTORY.fr.md))."),
  "it": ("Cronologia della chat e pulsante verso il browser web-grab", "Sotto la chat c’è ora l’elenco delle tue conversazioni: cercale, aprine una per rileggerla e continuare da dove eri rimasto, eliminane una o tutte. Restano solo nel tuo browser. In «Importa da altrove» un nuovo pulsante apre il browser web-grab sulla stessa libreria. Puoi anche salvare tutta la cronologia in un file e reimportarla; è lo stesso formato aperto di Colibri Companion ([docs/CHAT-HISTORY.it.md](../CHAT-HISTORY.it.md))."),
  "es": ("Historial del chat y botón al navegador web-grab", "Bajo el chat hay ahora una lista de tus conversaciones: búscalas, abre una para leerla y seguir donde lo dejaste, borra una o todas. Solo se guardan en tu navegador. En «Traer cosas de otro sitio» un botón nuevo abre el navegador web-grab sobre la misma biblioteca. También puedes guardar todo el historial en un archivo e importarlo de nuevo; es el mismo formato abierto que usa Colibri Companion ([docs/CHAT-HISTORY.es.md](../CHAT-HISTORY.es.md))."),
  "pt": ("Histórico do chat e botão para o navegador web-grab", "Por baixo do chat há agora a lista das tuas conversas: pesquisa-as, abre uma para a ler e continuar onde ficaste, apaga uma ou todas. Ficam guardadas só no teu navegador. Em «Trazer coisas de fora» um botão novo abre o navegador web-grab na mesma biblioteca. Também podes guardar todo o histórico num ficheiro e importá-lo de novo; é o mesmo formato aberto do Colibri Companion ([docs/CHAT-HISTORY.pt.md](../CHAT-HISTORY.pt.md))."),
  "de": ("Chat-Verlauf und Schaltfläche zum Web-Grab-Browser", "Unter dem Chat steht jetzt die Liste deiner bisherigen Gespräche: durchsuchen, eines öffnen, lesen und dort weitermachen, wo du aufgehört hast, eines oder alle löschen. Sie bleiben nur in deinem Browser. Unter „Etwas hereinholen“ öffnet eine neue Schaltfläche den Web-Grab-Browser mit derselben Bibliothek. Du kannst den ganzen Verlauf auch als eine Datei speichern und wieder importieren; es ist dasselbe offene Format wie in Colibri Companion ([docs/CHAT-HISTORY.de.md](../CHAT-HISTORY.de.md))."),
  "hu": ("Csevegési előzmények és gomb a web-grab böngészőhöz", "A csevegés alatt most ott a korábbi beszélgetéseid listája: kereshetsz bennük, megnyithatsz egyet, hogy elolvasd és ott folytasd, ahol abbahagytad, törölhetsz egyet vagy mindet. Csak a böngésződben tárolódnak. A „Behozatal máshonnan” ablakban egy új gomb megnyitja a web-grab böngészőt ugyanazzal a könyvtárral. Az egész előzményt egyetlen fájlba is mentheted, és vissza is importálhatod; ugyanaz a nyílt formátum, mint a Colibri Companionban ([docs/CHAT-HISTORY.hu.md](../CHAT-HISTORY.hu.md)).")},
 {"en": ("OCR with LegatorOCR, “Delete selected”, readable skip reasons", "Scans and photos can now be read through LegatorOCR, the same program Colibri Companion uses (tesseract still works). A new “Delete selected” button, `cartacolibri forget` and a ✕ beside skipped files take them out of the library for good, without touching the files. The reasons a file was skipped now appear in your language, and the 80 MB size limit can be raised with CARTACOLIBRI_MAX_FILE_MB."),
  "ro": ("OCR cu LegatorOCR, „Șterge selectatele”, motive de omitere clare", "Scanările și pozele se pot citi acum prin LegatorOCR, același program pe care îl folosește Colibri Companion (tesseract merge în continuare). Un buton nou „Șterge selectatele”, `cartacolibri forget` și un ✕ lângă fișierele omise le scot definitiv din bibliotecă, fără să atingă fișierele. Motivele pentru care un fișier a fost omis apar acum în limba ta, iar limita de 80 MB se poate mări cu CARTACOLIBRI_MAX_FILE_MB."),
  "fr": ("OCR avec LegatorOCR, « Supprimer la sélection », raisons d’omission lisibles", "Les scans et les photos peuvent maintenant être lus via LegatorOCR, le même programme que Colibri Companion (tesseract fonctionne toujours). Un nouveau bouton « Supprimer la sélection », `cartacolibri forget` et un ✕ à côté des fichiers ignorés les retirent pour de bon de la bibliothèque, sans toucher aux fichiers. Les raisons d’omission s’affichent dans ta langue, et la limite de 80 Mo se relève avec CARTACOLIBRI_MAX_FILE_MB."),
  "it": ("OCR con LegatorOCR, «Elimina i selezionati», motivi di esclusione leggibili", "Scansioni e foto si possono ora leggere con LegatorOCR, lo stesso programma di Colibri Companion (tesseract funziona ancora). Un nuovo pulsante «Elimina i selezionati», `cartacolibri forget` e una ✕ accanto ai file saltati li tolgono per sempre dalla libreria, senza toccare i file. I motivi per cui un file è stato saltato appaiono nella tua lingua e il limite di 80 MB si alza con CARTACOLIBRI_MAX_FILE_MB."),
  "es": ("OCR con LegatorOCR, «Borrar la selección», motivos de omisión legibles", "Los escaneos y las fotos ya se pueden leer con LegatorOCR, el mismo programa que usa Colibri Companion (tesseract sigue funcionando). Un botón nuevo «Borrar la selección», `cartacolibri forget` y una ✕ junto a los archivos omitidos los quitan para siempre de la biblioteca, sin tocar los archivos. Los motivos de omisión salen ahora en tu idioma y el límite de 80 MB se sube con CARTACOLIBRI_MAX_FILE_MB."),
  "pt": ("OCR com LegatorOCR, «Apagar os selecionados», motivos de omissão legíveis", "As digitalizações e as fotos já se podem ler com o LegatorOCR, o mesmo programa que o Colibri Companion usa (o tesseract continua a funcionar). Um botão novo «Apagar os selecionados», `cartacolibri forget` e um ✕ junto dos ficheiros ignorados tiram-nos em definitivo da biblioteca, sem tocar nos ficheiros. Os motivos de omissão aparecem agora na tua língua e o limite de 80 MB sobe-se com CARTACOLIBRI_MAX_FILE_MB."),
  "de": ("OCR mit LegatorOCR, „Auswahl löschen“, lesbare Überspringgründe", "Scans und Fotos lassen sich jetzt mit LegatorOCR lesen, demselben Programm wie in Colibri Companion (Tesseract funktioniert weiterhin). Eine neue Schaltfläche „Auswahl löschen“, `cartacolibri forget` und ein ✕ neben übersprungenen Dateien nehmen sie dauerhaft aus der Bibliothek, ohne die Dateien anzufassen. Die Gründe fürs Überspringen erscheinen jetzt in deiner Sprache, und das 80-MB-Limit lässt sich mit CARTACOLIBRI_MAX_FILE_MB anheben."),
  "hu": ("OCR a LegatorOCR-rel, „Kijelöltek törlése”, érthető kihagyási okok", "A beolvasott lapokat és fotókat mostantól a LegatorOCR is olvashatja, ugyanaz a program, amit a Colibri Companion használ (a tesseract továbbra is működik). Az új „Kijelöltek törlése” gomb, a `cartacolibri forget` és a kihagyott fájlok melletti ✕ véglegesen kiveszi őket a könyvtárból, a fájlokhoz nem nyúlva. A kihagyás okai most az általad választott nyelven jelennek meg, a 80 MB-os korlát pedig a CARTACOLIBRI_MAX_FILE_MB-vel emelhető.")},
]


def _s(n, tab, cap, text):
    L = ["en", "ro", "fr", "it", "es", "pt", "de", "hu"]
    t = {l: tab[i] for i, l in enumerate(L)}
    c = {l: cap[i] for i, l in enumerate(L)}
    x = {l: text[i] for i, l in enumerate(L)}
    return n, {"title": {l: f"{n} · {t[l]}" for l in L}, "tab": t, "cap": c, "text": x}


